INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-01', 'Product Safety & Hazard', 'CRITICAL', 'Safety & Regulatory Escalations', True);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-02', 'Defective / Damaged Item', 'HIGH', 'Product Quality Team', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-03', 'Late or Missing Delivery', 'MEDIUM', 'Logistics & Fulfillment', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-04', 'Billing & Overcharge', 'HIGH', 'Finance & Billing Ops', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-05', 'Refund & Return Processing', 'MEDIUM', 'Returns & Settlement', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-06', 'Account Access & Security', 'HIGH', 'Security & Identity', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-07', 'Poor Customer Service', 'MEDIUM', 'Service Excellence Team', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-08', 'Missing Parts / Accessories', 'LOW', 'Inventory & Parts Ops', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-09', 'Misleading Description', 'LOW', 'Catalog & Compliance', False);
INSERT INTO categories (category_id, category_name, default_severity, assigned_team, is_safety_critical) VALUES ('CAT-10', 'Technical & Software Glitch', 'MEDIUM', 'Technical Support Tier 2', False);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-01', 'Safety Hazard Automatic Critical', 'is_safety_issue == True OR category == ''Product Safety & Hazard''', 'P1_CRITICAL', 1, 4);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-02', 'Vulnerable Customer Negative Sentiment', 'is_vulnerable == True AND sentiment_score < -0.40', 'P1_CRITICAL', 1, 4);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-03', 'Vulnerable Customer Standard Escalation', 'is_vulnerable == True', 'P2_HIGH', 4, 24);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-04', 'High Value Recurring Order Complaint', 'order_amount >= 1000.00 AND is_repeat_complaint == True', 'P2_HIGH', 4, 24);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-05', 'Severe Frustration Negative Sentiment', 'sentiment_score <= -0.70', 'P2_HIGH', 4, 24);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-06', 'High Value Standard or Repeat Complaint', 'order_amount >= 500.00 OR is_repeat_complaint == True', 'P3_MEDIUM', 12, 48);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-07', 'Default High Severity', 'severity == ''HIGH''', 'P2_HIGH', 4, 24);
INSERT INTO priority_rules (rule_id, rule_name, condition_expression, target_priority, target_response_hours, target_resolution_hours) VALUES ('RUL-08', 'Standard Low Priority Baseline', 'DEFAULT', 'P4_LOW', 24, 96);
